// Generates a minimal placeholder public/Venugopal_V_Resume.pdf.
// REPLACE this file with the real resume PDF before going live (see README).
import { writeFileSync, mkdirSync } from "node:fs";

const lines = [
  "Venugopal V - AI/ML Engineer Intern",
  "Madurai, Tamil Nadu, India",
  "Email: Venu25122005@gmail.com | LinkedIn: linkedin.com/in/venugopal-v-61a50b3a9",
  "GitHub: github.com/venu2512",
  "",
  "NOTE: This is a placeholder PDF generated by scripts/make-resume.mjs.",
  "Replace public/Venugopal_V_Resume.pdf with the real resume.",
  "",
  "Summary",
  "AI & Data Science student building multi-agent AI systems, machine learning",
  "solutions, and blockchain applications. Open to internships in Data Science,",
  "AI, and Blockchain.",
  "",
  "Experience",
  "KreupAI Technologies LLC - AI/ML Engineer Intern (May 2026 - Present)",
  "QuadEdutor Pvt. Ltd. - Data Science Intern",
  "Nitroware Technologies - AI & ML Intern",
  "",
  "Projects",
  "CertChain - Blockchain Certificate Verification System",
  "Legal AI Chatbot - Domain-specific legal assistant (Gemma + QLoRA)",
  "Cloud Nova - Full Stack MERN Web Application",
  "",
  "Education",
  "PPG Institute of Technology, Coimbatore - B.Tech AI & Data Science (2023-2027)",
  "MSR Matric Hr. Sec. School, Madurai - HSC (2020-2023)",
];

// Minimal single-page PDF, Helvetica 10pt, one text object.
const esc = (s) => s.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
const content = [
  "BT /F1 14 Tf 50 780 Td (Venugopal V - AI/ML Engineer Intern) Tj ET",
  ...lines.slice(1).map((l, i) => `BT /F1 10 Tf 50 ${760 - i * 14} Td (${esc(l)}) Tj ET`),
].join("\n");

const objs = [];
objs.push("<< /Type /Catalog /Pages 2 0 R >>");
objs.push("<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
objs.push("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>");
objs.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
objs.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");

let pdf = "%PDF-1.4\n";
const offsets = [0];
objs.forEach((o, i) => {
  offsets.push(pdf.length);
  pdf += `${i + 1} 0 obj\n${o}\nendobj\n`;
});
const xrefStart = pdf.length;
pdf += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n`;
for (let i = 1; i <= objs.length; i++) {
  pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
}
pdf += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;

mkdirSync("public", { recursive: true });
writeFileSync("public/Venugopal_V_Resume.pdf", pdf, "latin1");
console.log("public/Venugopal_V_Resume.pdf written (placeholder)");
